import React, { useState } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { addTask, markComplete, deleteTask } from './redux/actions';

function App() {
  const [taskInput, setTaskInput] = useState('');
  const tasks = useSelector(state => state.tasks);
  const dispatch = useDispatch();

  const handleAddTask = () => {
    if (taskInput.trim() === '') return;
    const newTask = {
      id: Date.now(),
      task: taskInput,
      inProgress: true
    };
    dispatch(addTask(newTask));
    setTaskInput('');
  };

  return (
    <div className="App">
      <h1>Redux Todo App</h1>
      <input
        type="text"
        value={taskInput}
        onChange={e => setTaskInput(e.target.value)}
        placeholder="Enter task here..."
      />
      <button onClick={handleAddTask}>Add Task</button>

      <table border="1" width="100%" style={{ marginTop: 20 }}>
        <thead>
          <tr>
            <th>No.</th>
            <th>Task</th>
            <th>Status</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {tasks.length === 0 ? (
            <tr><td colSpan="4">No tasks</td></tr>
          ) : (
            tasks.map((task, index) => (
              <tr key={task.id}>
                <td>{index + 1}</td>
                <td>{task.task}</td>
                <td>{task.inProgress ? 'In Progress' : 'Completed'}</td>
                <td>
                  {task.inProgress && (
                    <button onClick={() => dispatch(markComplete(task.id))}>
                      Mark Complete
                    </button>
                  )}
                  <button onClick={() => dispatch(deleteTask(task.id))}>
                    Delete
                  </button>
                </td>
              </tr>
            ))
          )}
        </tbody>
      </table>
    </div>
  );
}

export default App;
